"""Persistence for orders."""


class OrderRepository:
    def __init__(self, db):
        self.db = db

    def get_order(self, order_id):
        return self.db.fetch_one("orders", order_id)

    def save_order(self, order):
        return self.db.upsert("orders", order)

    def delete_order(self, order_id):
        return self.db.delete("orders", order_id)

    def list_orders(self, customer_id, status):
        return self.db.query("orders", customer_id=customer_id, status=status)

