"""Order field validators, one per field."""


def check_sku(sku):
    return bool(sku) and sku.isalnum()


def check_quantity(quantity):
    return 0 < quantity <= 999


def check_currency(currency):
    return currency in ("EUR", "USD", "GBP")


def check_postcode(postcode, country):
    return bool(postcode) and len(postcode) <= 10


def check_email(email):
    return "@" in email

