"""Prices an order: line totals, tiered discounts, tax, rounding at the end."""
from decimal import Decimal, ROUND_HALF_EVEN
from orders.tax_tables import _RATES

__all__ = ["price_order"]

_TIERS = [(Decimal("1000"), Decimal("0.10")), (Decimal("500"), Decimal("0.05"))]


def price_order(order, catalog):
    """Return a fully priced order. Rounds once, after summing, to avoid drift."""
    lines = []
    subtotal = Decimal("0")
    for item in order["items"]:
        product = catalog[item["sku"]]
        unit = Decimal(str(product["price"]))
        qty = Decimal(item["quantity"])
        line = unit * qty
        if product.get("bundle_discount") and qty >= 3:
            line -= line * Decimal(str(product["bundle_discount"]))
        lines.append({"sku": item["sku"], "amount": line})
        subtotal += line
    discount = _tier_discount(subtotal)
    taxable = subtotal - discount
    rate = _RATES.get(order["country"], Decimal("0"))
    tax = taxable * rate
    total = taxable + tax
    return {
        "lines": [_round_line(l) for l in lines],
        "subtotal": _money(subtotal),
        "discount": _money(discount),
        "tax": _money(tax),
        "total": _money(total),
    }


def _tier_discount(subtotal):
    for threshold, pct in _TIERS:
        if subtotal >= threshold:
            return subtotal * pct
    return Decimal("0")


def _round_line(line):
    return {"sku": line["sku"], "amount": _money(line["amount"])}


def _money(value):
    return value.quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)

