// Checkout: callers must assemble every pricing input themselves.
import { _applyTax, _roundMoney } from "./pricing-internals";

export function submitCheckout(cartId: string, items: Item[], country: string, currency: string,
  couponCode: string, taxExempt: boolean, retryCount: number) {
  const subtotal = items.reduce((s, i) => s + i.price * i.qty, 0);
  const taxed = taxExempt ? subtotal : _applyTax(subtotal, country);
  const total = _roundMoney(taxed, currency);
  if (retryCount > 3) {
    throw new Error("too many retries");
  }
  return { cartId, total, couponCode };
}

