// Cart: owns line merging, stock limits, coupon rules and persistence behind three methods.
export class Cart {
  private lines: Map<string, number> = new Map();
  private coupon: string | null = null;

  constructor(private store: CartStore, private stock: StockLookup) {}

  add(sku: string, qty: number) {
    const current = this.lines.get(sku) ?? 0;
    const limit = this.stock.available(sku);
    const next = Math.min(current + qty, limit, 99);
    if (next <= 0) {
      this.lines.delete(sku);
    } else {
      this.lines.set(sku, next);
    }
    this.revalidateCoupon();
    this.store.save(this.snapshot());
  }

  applyCoupon(code: string) {
    const normalised = code.trim().toUpperCase();
    if (!/^[A-Z0-9]{4,12}$/.test(normalised)) {
      return false;
    }
    this.coupon = normalised;
    this.revalidateCoupon();
    this.store.save(this.snapshot());
    return this.coupon !== null;
  }

  snapshot() {
    return {
      lines: Array.from(this.lines.entries()).map(([sku, qty]) => ({ sku, qty })),
      coupon: this.coupon,
      itemCount: Array.from(this.lines.values()).reduce((a, b) => a + b, 0),
    };
  }

  private revalidateCoupon() {
    if (this.coupon === null) {
      return;
    }
    const count = Array.from(this.lines.values()).reduce((a, b) => a + b, 0);
    if (count === 0) {
      this.coupon = null;
    }
    if (this.coupon && this.coupon.startsWith("BULK") && count < 10) {
      this.coupon = null;
    }
  }
}
